<script setup>
import { computed } from 'vue'
const props=defineProps({accounts:{type:Array,default:()=>[]},currencies:{type:Array,default:()=>[]},baseCurrencyCode:String,disabled:Boolean,minLines:{type:Number,default:2}})
const lines=defineModel('lines',{type:Array,required:true})
const types={asset:'الأصول',liability:'الالتزامات',equity:'حقوق الملكية',revenue:'الإيرادات',contra_revenue:'مقابلات الإيراد',expense:'المصاريف'}
const groups=computed(()=>Object.entries(types).map(([key,label])=>({key,label,items:props.accounts.filter(a=>a.type===key)})).filter(g=>g.items.length))
const baseAmount=(amount,rate)=>Number(amount||0)*Number(rate||1);const totalDebit=computed(()=>lines.value.reduce((s,l)=>s+baseAmount(l.foreign_debit,l.exchange_rate),0));const totalCredit=computed(()=>lines.value.reduce((s,l)=>s+baseAmount(l.foreign_credit,l.exchange_rate),0));const difference=computed(()=>totalDebit.value-totalCredit.value);const balanced=computed(()=>Math.abs(difference.value)<.01&&totalDebit.value>0)
function emptyLine(){return{account_id:'',foreign_debit:'',foreign_credit:'',currency_code:props.baseCurrencyCode,exchange_rate:1,description:'',details:false}}
function add(){lines.value=[...lines.value,emptyLine()]}
function remove(index){if(lines.value.length<=props.minLines)return;lines.value=lines.value.filter((_,i)=>i!==index)}
function debit(line){if(Number(line.foreign_debit)>0)line.foreign_credit=''}function credit(line){if(Number(line.foreign_credit)>0)line.foreign_debit=''}
function currencyChanged(line){const currency=props.currencies.find(c=>c.code===line.currency_code);line.exchange_rate=currency?.base?1:(currency?.rate||'')}
defineExpose({balanced,totalDebit,totalCredit,difference})
</script>
<template><section class="lines-editor"><header><div><strong>سطور القيد</strong><small>كل سطر يحتوي جهة واحدة فقط: مدين أو دائن.</small></div><button type="button" :disabled="disabled" @click="add"><i class="bi bi-plus-lg"></i> سطر جديد</button></header><div class="lines"><article v-for="(line,index) in lines" :key="index"><span class="number">{{index+1}}</span><label class="account"><span>الحساب</span><select v-model="line.account_id" class="form-select" required :disabled="disabled"><option value="">اختر حساباً</option><optgroup v-for="group in groups" :key="group.key" :label="group.label"><option v-for="account in group.items" :key="account.id" :value="account.id">{{account.code}} — {{account.name}}{{account.system?' 🔒':''}}</option></optgroup></select></label><label><span>مدين</span><input v-model="line.foreign_debit" type="number" step=".0001" min="0" class="form-control amount" placeholder="0.00" :disabled="disabled" @input="debit(line)"></label><label><span>دائن</span><input v-model="line.foreign_credit" type="number" step=".0001" min="0" class="form-control amount" placeholder="0.00" :disabled="disabled" @input="credit(line)"></label><button type="button" class="details" :class="{open:line.details}" :disabled="disabled" title="عملة أو وصف" :aria-label="`تفاصيل السطر ${index+1}`" @click="line.details=!line.details"><i class="bi bi-sliders"></i></button><button type="button" class="remove" :aria-label="`حذف السطر ${index+1}`" :disabled="disabled||lines.length<=minLines" @click="remove(index)"><i class="bi bi-trash3"></i></button><div v-if="line.details" class="line-details"><label><span>العملة</span><select v-model="line.currency_code" class="form-select" :disabled="disabled" @change="currencyChanged(line)"><option v-for="currency in currencies" :key="currency.code" :value="currency.code">{{currency.code}} — {{currency.name}}</option></select></label><label><span>سعر الصرف إلى {{baseCurrencyCode}}</span><input v-model="line.exchange_rate" type="number" min=".000001" step=".000001" class="form-control" :disabled="disabled||line.currency_code===baseCurrencyCode"></label><label class="description"><span>وصف السطر</span><input v-model="line.description" class="form-control" maxlength="255" :disabled="disabled"></label></div></article></div><footer><span><small>إجمالي مدين</small><strong>{{totalDebit.toFixed(2)}} {{baseCurrencyCode}}</strong></span><span><small>إجمالي دائن</small><strong>{{totalCredit.toFixed(2)}} {{baseCurrencyCode}}</strong></span><span class="state" :class="balanced?'ok':'bad'"><i class="bi" :class="balanced?'bi-check-circle-fill':'bi-exclamation-triangle-fill'"></i><strong>{{balanced?'القيد متوازن':`فرق ${Math.abs(difference).toFixed(2)} ${baseCurrencyCode}`}}</strong></span></footer></section></template>
<style scoped>.lines-editor{overflow:hidden;border:1px solid var(--line, #DFD7CB);border-radius:12px;background:var(--surface, #FFFDFA)}.lines-editor>header{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;border-bottom:1px solid var(--line, #DFD7CB);background:var(--surface, #FFFDFA)}.lines-editor>header>div{display:grid}.lines-editor>header strong{font-size:.875rem}.lines-editor>header small{color:var(--muted, #626B6D);font-size:.875rem}.lines-editor>header button{padding:7px 10px;border:1px solid var(--line, #DFD7CB);border-radius:8px;color:var(--ink, #25343A);background:var(--surface, #FFFDFA);font-size:.875rem;font-weight:850}.lines{display:grid}.lines article{display:grid;grid-template-columns:28px minmax(220px,1.5fr) minmax(105px,.55fr) minmax(105px,.55fr) 34px 34px;align-items:end;gap:7px;padding:9px 12px;border-bottom:1px solid var(--line, #DFD7CB)}.lines article>label,.line-details label{display:grid;gap:3px}.lines label>span{font-size:.875rem;font-weight:800}.number{display:grid;width:25px;height:25px;place-items:center;align-self:center;border-radius:8px;color:var(--ink, #25343A);background:var(--brand-soft, #F3E3D8);font-size:.875rem;font-weight:900}.amount{text-align:end}.details,.remove{display:grid;width:33px;height:33px;place-items:center;border:1px solid var(--line, #DFD7CB);border-radius:8px;color:var(--muted, #626B6D);background:var(--surface, #FFFDFA)}.details.open{color:var(--ink, #25343A);border-color:var(--line, #DFD7CB);background:var(--surface, #FFFDFA)}.remove{color:#ad3030}.line-details{display:grid;grid-column:2/-1;grid-template-columns:150px 170px 1fr;gap:8px;padding:8px;border-radius:10px;background:var(--surface, #FFFDFA)}.lines-editor>footer{display:grid;grid-template-columns:160px 160px 1fr;align-items:center;gap:9px;padding:11px 14px;background:var(--surface, #FFFDFA)}.lines-editor>footer>span{display:grid}.lines-editor footer small{color:var(--muted, #626B6D);font-size:.875rem}.lines-editor footer strong{font-size:.875rem}.state{display:flex!important;align-items:center;justify-content:flex-end;gap:6px}.state.ok{color:var(--ink, #25343A)}.state.bad{color:#ad2929}@media(max-width:850px){.lines article{grid-template-columns:28px 1fr 1fr 34px}.lines .account{grid-column:2/-1}.lines .details{grid-column:3}.line-details{grid-column:2/-1;grid-template-columns:1fr 1fr}.line-details .description{grid-column:1/-1}}@media(max-width:520px){.lines article{grid-template-columns:24px 1fr 1fr}.lines .account{grid-column:2/-1}.lines .details{grid-column:2}.lines .remove{grid-column:3}.line-details{grid-column:1/-1}.lines-editor>footer{grid-template-columns:1fr 1fr}.state{grid-column:1/-1;justify-content:flex-start}.lines-editor>header small{display:none}}
.lines-editor{border-radius:16px}.lines-editor>header{padding:20px}.lines-editor>header strong{font-size:18px}.lines article{gap:14px;padding:20px;grid-template-columns:30px minmax(220px,1.5fr) minmax(120px,.55fr) minmax(120px,.55fr) 40px 40px}.lines article:nth-child(even){background:#F7F3ED}.lines .form-control,.lines .form-select{min-height:46px;font-size:15px}.lines label>span{font-size:13px}.details,.remove{width:40px;height:46px}.line-details{gap:16px;padding:18px;margin-top:4px;background:#EFE9E0}.lines-editor>footer{grid-template-columns:1fr 1fr 1.3fr;gap:20px;padding:20px;border-top:2px solid #DFD7CB;background:#F7F3ED}.lines-editor footer strong{font-size:18px}.lines-editor footer small{font-size:13px}.state.ok{color:#25343A}.number{background:transparent;color:#626B6D;font-size:14px}@media(max-width:1000px){.lines article{grid-template-columns:30px 1fr 1fr 40px}.lines .account{grid-column:2/-1}.lines .details{grid-column:3}.line-details{grid-column:2/-1;grid-template-columns:1fr 1fr}.line-details .description{grid-column:1/-1}}@media(max-width:550px){.lines article{grid-template-columns:24px 1fr 1fr;padding:16px;gap:10px}.lines .details{grid-column:2}.lines .remove{grid-column:3}.line-details{grid-column:1/-1}.lines-editor>footer{grid-template-columns:1fr 1fr}.state{grid-column:1/-1}}
</style>
